# Print each number from 1 to 5
for number in range(1, 6):
    print(number)

# Repeat an inner loop inside an outer loop
for outer in range(1, 3):
    for inner in range(1, 4):
        print(outer, inner)

# Skip 3 with continue, stop at 5 with break
for number in range(1, 7):
    if number == 3:
        continue
    if number == 5:
        break
    print(number)
